**What this code covers**

- Create index with proper field types and analyzers
- Index/Update product in Elasticsearch
- Full reindex — run nightly or after schema changes
- Ultra-fast autocomplete using edge n-grams
- ❌ WRONG: This dies at 10K products, unusable at 1M products
- ✅ Production Search Implementation
- 1. Index documents with proper mappings
- 2. Search endpoint with caching and ranking

**Defines:** `search_products()`, `create_product_index()`, `search()`, `index_product()`, `bulk_reindex()`, `autocomplete()`

### The Problem with Database LIKE Queries

```python
# ❌ WRONG: This dies at 10K products, unusable at 1M products
@app.get("/search")
def search_products(q: str):
    results = db.query(Product).filter(
        Product.name.ilike(f"%{q}%")
    ).all()  # ← Full table scan = 30 seconds on 1M rows
    return results
```

### The Right Way: Dedicated Search Engine

```
┌─────────────────────────────────────────────────────────────────┐
│                    SEARCH ARCHITECTURE                          │
│                                                                 │
│  User Query → API Server → Elasticsearch/Typesense             │
│                 ↓                                               │
│          Cache Results                                          │
│                                                                 │
│  Write/Update → API Server → PostgreSQL (primary)              │
│                 ↓                                               │
│           Kafka/Queue → Search Indexer Worker                   │
│                                   ↓                             │
│                            Elasticsearch/Typesense              │
└─────────────────────────────────────────────────────────────────┘
```

### Implementation: Elasticsearch at Scale

```python
# ✅ Production Search Implementation

from elasticsearch import Elasticsearch
from fastapi import FastAPI, HTTPException
from redis import Redis
import hashlib
import json

app = FastAPI()
es = Elasticsearch(["http://es-cluster:9200"])
redis_cache = Redis(host="redis", decode_responses=True)

# 1. Index documents with proper mappings
def create_product_index():
    """Create index with proper field types and analyzers"""
    index_config = {
        "settings": {
            "number_of_shards": 5,  # Distribute across 5 nodes
            "number_of_replicas": 2,  # 2 copies for high availability
            "refresh_interval": "5s",  # Balance between freshness and performance
            "analysis": {
                "analyzer": {
                    "autocomplete": {
                        "type": "custom",
                        "tokenizer": "standard",
                        "filter": ["lowercase", "edge_ngram"]
                    }
                },
                "filter": {
                    "edge_ngram": {
                        "type": "edge_ngram",
                        "min_gram": 2,
                        "max_gram": 10
                    }
                }
            }
        },
        "mappings": {
            "properties": {
                "name": {
                    "type": "text",
                    "analyzer": "autocomplete",
                    "search_analyzer": "standard",
                    "fields": {
                        "keyword": {"type": "keyword"}  # For exact matches
                    }
                },
                "description": {"type": "text"},
                "category": {"type": "keyword"},  # For filtering
                "price": {"type": "float"},
                "stock": {"type": "integer"},
                "rating": {"type": "float"},
                "created_at": {"type": "date"}
            }
        }
    }
    es.indices.create(index="products", body=index_config, ignore=400)

# 2. Search endpoint with caching and ranking
@app.get("/search")
async def search(
    q: str,
    page: int = 1,
    category: str = None,
    min_price: float = None,
    max_price: float = None
):
    # Generate cache key
    cache_key = f"search:{hashlib.md5(f'{q}:{page}:{category}:{min_price}:{max_price}'.encode()).hexdigest()}"

    # Check cache first
    cached = redis_cache.get(cache_key)
    if cached:
        return json.loads(cached)

    # Build search query
    must_conditions = [
        {
            "multi_match": {
                "query": q,
                "fields": ["name^3", "description"],  # name is 3x more important
                "fuzziness": "AUTO",  # Handle typos
                "prefix_length": 2
            }
        }
    ]

    filter_conditions = []
    if category:
        filter_conditions.append({"term": {"category": category}})
    if min_price or max_price:
        price_range = {}
        if min_price:
            price_range["gte"] = min_price
        if max_price:
            price_range["lte"] = max_price
        filter_conditions.append({"range": {"price": price_range}})

    search_body = {
        "query": {
            "bool": {
                "must": must_conditions,
                "filter": filter_conditions
            }
        },
        "from": (page - 1) * 20,
        "size": 20,
        "sort": [
            "_score",  # Relevance first
            {"rating": "desc"},  # Then by rating
            {"created_at": "desc"}  # Then by recency
        ],
        "highlight": {
            "fields": {
                "name": {},
                "description": {}
            }
        }
    }

    # Execute search
    response = es.search(index="products", body=search_body)

    # Format results
    results = {
        "total": response["hits"]["total"]["value"],
        "page": page,
        "results": [
            {
                "id": hit["_id"],
                "name": hit["_source"]["name"],
                "price": hit["_source"]["price"],
                "rating": hit["_source"]["rating"],
                "highlight": hit.get("highlight", {})
            }
            for hit in response["hits"]["hits"]
        ]
    }

    # Cache for 5 minutes
    redis_cache.setex(cache_key, 300, json.dumps(results))

    return results

# 3. Background indexing worker (Celery task)
from celery import Celery
celery_app = Celery("tasks", broker="redis://redis:6379")

@celery_app.task
def index_product(product_id: int):
    """Index/Update product in Elasticsearch"""
    # Fetch from PostgreSQL
    product = db.query(Product).filter(Product.id == product_id).first()

    # Index in Elasticsearch
    doc = {
        "name": product.name,
        "description": product.description,
        "category": product.category,
        "price": product.price,
        "stock": product.stock,
        "rating": product.rating,
        "created_at": product.created_at
    }

    es.index(index="products", id=product_id, body=doc)

@celery_app.task
def bulk_reindex():
    """Full reindex — run nightly or after schema changes"""
    products = db.query(Product).all()

    # Bulk indexing (1000x faster than one-by-one)
    bulk_data = []
    for product in products:
        bulk_data.append({"index": {"_index": "products", "_id": product.id}})
        bulk_data.append({
            "name": product.name,
            "description": product.description,
            "category": product.category,
            "price": product.price,
            "stock": product.stock,
            "rating": product.rating
        })

        # Send batch every 1000 products
        if len(bulk_data) >= 2000:  # 1000 products × 2 lines each
            es.bulk(body=bulk_data)
            bulk_data = []

    # Send remaining
    if bulk_data:
        es.bulk(body=bulk_data)
```

### Autocomplete at Scale

```python
@app.get("/autocomplete")
async def autocomplete(q: str, limit: int = 10):
    """Ultra-fast autocomplete using edge n-grams"""

    cache_key = f"autocomplete:{q.lower()}"
    cached = redis_cache.get(cache_key)
    if cached:
        return json.loads(cached)

    search_body = {
        "query": {
            "match": {
                "name": {
                    "query": q,
                    "analyzer": "autocomplete"
                }
            }
        },
        "size": limit,
        "_source": ["name"]  # Only return name field (faster)
    }

    response = es.search(index="products", body=search_body)
    suggestions = [hit["_source"]["name"] for hit in response["hits"]["hits"]]

    # Cache for 1 hour (autocomplete queries are repetitive)
    redis_cache.setex(cache_key, 3600, json.dumps(suggestions))

    return {"suggestions": suggestions}
```

### Search Performance Numbers

```
PostgreSQL ILIKE on 1M rows:     15-30 seconds ❌
PostgreSQL Full-Text Search:     2-5 seconds   ⚠️
Elasticsearch (properly indexed): 10-50ms       ✅
Elasticsearch + Redis cache:      1-5ms        🚀

At 1 million products:
- PostgreSQL LIKE = Unusable
- Elasticsearch = 10,000 searches/second per node
- With 5-node cluster = 50,000 searches/second
```
